__NUXT_JSONP__("/fr/school-calendar", {data:[{details:{slug:"fr",pageTitle:"Calendrier scolaire | Mentor Language Institute",pageDescription:"La date de début du programme varie selon les étudiants F1 ou non F1.",title:"Calendrier scolaire",calendar:[{year:"2026",image:"\u002Fimages\u002Fcourses\u002Fschool-calendar\u002F2026.PNG"},{year:"2027",image:"\u002Fimages\u002Fcourses\u002Fschool-calendar\u002F2027.png"}],notes:["\u003Cfont color=\"#FECC13\"\u003EJaune\u003C\u002Ffont\u003E: date de début du programme (module)\u003Cbr \u002F\u003E\u003Cfont color=\"”#008000”\"\u003EVert\u003C\u002Ffont\u003E： pas d'école (vacances)"],schoolCalendar:{title:"Calendrier scolaire (dates de début du programme)",description:["\u003Cspan class=\"ymarker\"\u003ELa date de début du programme varie selon les étudiants F1 ou non F1.\u003C\u002Fspan\u003E"],lists:[{key:"Étudiants non-F1 qui n'obtiennent pas de visa étudiant.",value:["Ils peuvent commencer leur programme tous les lundis. \u003Cbr\u003E Si le lundi est un jour férié, la date de début du programme sera le mardi pour cette semaine."]},{key:"Les étudiants F1 qui obtiennent un visa d’étudiant (F).",value:["Peut commencer certains lundis. (surligné en jaune dans le calendrier).","\u003C2026\u003E \u003Cbr \u002F\u003E1\u002F20, 2\u002F17, 3\u002F16, 4\u002F13, 5\u002F11, 6\u002F8, 7\u002F6, 8\u002F3, 8\u002F31, 9\u002F28, 10\u002F26, 11\u002F23, 12\u002F21","\u003C2027\u003E\u003Cbr \u002F\u003E 1\u002F25, 2\u002F22, 3\u002F22, 4\u002F19, 5\u002F17, 6\u002F14, 7\u002F12, 8\u002F9, 9\u002F7, 10\u002F4, 11\u002F1, 11\u002F29","\u003C2028\u003E \u003Cbr \u002F\u003E 1\u002F3"]}]},faq:{title:"Questions fréquemment posées sur les dates d'arrivée aux États-Unis",lists:[{key:"\u003Cb\u003EQ: Combien de jours avant la date de début du programme un étudiant peut-il entrer aux États-Unis? \u003C\u002Fb\u003E",value:["R: MLI n’exige pas de nos étudiants qu’ils se rendent aux États-Unis un nombre spécifique de jours à l’avance. Cependant, nos étudiants entrent généralement aux États-Unis un ou deux jours avant la date de début de leur programme."],note:"Remarque: les étudiants internationaux sont autorisés à entrer aux États-Unis 30 jours avant la date de début de leur programme."},{key:"\u003Cb\u003EQ: Est-il possible d'emménager dans l'hébergement avant les dates de début du programme? \u003C\u002Fb\u003E",value:["A: oui Nous pouvons organiser votre hébergement avec une date d'emménagement quelconque.\u003Cbr \u002F\u003ES'il y a d'autres questions, n'hésitez pas à nous consulter."]}]},dir:"\u002Fschool-calendar",path:"\u002Fschool-calendar\u002Ffr",extension:".json",createdAt:"2026-10-22T16:31:30.868Z",updatedAt:"2026-04-24T11:47:24.292Z"}}],fetch:{},mutations:void 0});